const { useState } = React;

function App() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = (e) => {
    e.preventDefault();
    if (!email.trim() || !password.trim()) {
      setError("Please enter both email and password.");
    } else {
      setError("");
      // Normally here would be login logic
      alert(`Logging in with email: ${email}`);
    }
  };

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #fff;
          color: #222;
        }
        header {
          display: flex;
          align-items: center;
          padding: 0.5rem 1rem;
          border-bottom: 1px solid #ddd;
          background: #f9f9f9;
        }
        .logo {
          font-weight: 700;
          font-size: 1.25rem;
          margin-right: 1rem;
          user-select: none;
        }
        form {
          display: flex;
          align-items: center;
          gap: 0.75rem;
          flex-wrap: nowrap;
          flex-grow: 1;
          max-width: 600px;
        }
        input[type="email"], input[type="password"] {
          flex: 1 1 0;
          padding: 0.5rem 0.75rem;
          font-size: 1rem;
          border: 1px solid #ccc;
          border-radius: 4px;
          transition: border-color 0.2s;
        }
        input[type="email"]:focus, input[type="password"]:focus {
          outline: none;
          border-color: #007bff;
          box-shadow: 0 0 3px #007bff;
        }
        button {
          padding: 0.5rem 1.25rem;
          font-size: 1rem;
          border: 1px solid #007bff;
          background-color: #007bff;
          color: white;
          border-radius: 20px;
          cursor: pointer;
          user-select: none;
          transition: background-color 0.2s, border-color 0.2s;
        }
        button:hover {
          background-color: #0056b3;
          border-color: #0056b3;
        }
        main {
          max-width: 900px;
          margin: 2rem auto;
          padding: 0 1rem;
        }
        h1 {
          font-weight: 700;
          font-size: 2rem;
          margin-bottom: 0.5rem;
        }
        p {
          margin-top: 0;
          margin-bottom: 1.5rem;
          line-height: 1.5;
          color: #444;
        }
        .banner {
          width: 100%;
          height: 250px;
          object-fit: cover;
          border-radius: 8px;
          box-shadow: 0 2px 8px rgb(0 0 0 / 0.1);
        }
        .error {
          color: #b00020;
          margin-top: 0.5rem;
          font-weight: 600;
        }
      `}</style>

      <header>
        <div className="logo" aria-label="Friendly logo">Friendly</div>
        <form onSubmit={handleLogin} noValidate>
          <label htmlFor="email" className="sr-only">Email</label>
          <input
            id="email"
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            aria-describedby={error ? "error-message" : undefined}
          />
          <label htmlFor="password" className="sr-only">Password</label>
          <input
            id="password"
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            aria-describedby={error ? "error-message" : undefined}
          />
          <button type="submit">Log In</button>
        </form>
      </header>

      <main>
        <h1>Connect with friends</h1>
        <p>
          Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.
        </p>
        {error && (
          <p id="error-message" role="alert" className="error">
            {error}
          </p>
        )}
        <img
          src="/runtime/photos/banner.jpg"
          alt="Banner showing a scenic landscape with mountains and sun"
          className="banner"
        />
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

